<template><div><el-button type="primary" size="mini" @click="show({})">新增决策</el-button><el-table :data="rows"><el-table-column prop="code" label="编码"/><el-table-column prop="title" label="标题"/><el-table-column prop="status" label="状态"/><el-table-column label="影响模板"><template slot-scope="scope">{{ (scope.row.impactedTemplateCodes || []).join(', ') }}</template></el-table-column><el-table-column label="操作"><template slot-scope="scope"><el-button type="text" @click="show(scope.row)">编辑</el-button><el-button v-if="scope.row.status !== 'OPEN'" type="text" @click="reopen(scope.row)">重新打开</el-button></template></el-table-column></el-table><el-dialog :title="form.decisionId ? '编辑决策' : '新增决策'" :visible.sync="open" :close-on-click-modal="false"><el-form :model="form" label-width="90px"><el-form-item label="编码" required><el-input v-model="form.code" :disabled="!!form.decisionId"/></el-form-item><el-form-item label="标题" required><el-input v-model="form.title"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="阻塞"><el-switch v-model="form.blocking"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="OPEN" value="OPEN"/><el-option label="RESOLVED" value="RESOLVED"/><el-option label="CLOSED" value="CLOSED"/></el-select></el-form-item><el-form-item v-if="form.status !== 'OPEN'" label="结论" required><el-input v-model="form.conclusion"/></el-form-item><el-form-item v-if="form.status !== 'OPEN'" label="处理方案" required><el-input v-model="form.resolution"/></el-form-item></el-form><span slot="footer"><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog></div></template>
<script>
import { createTodoDecision, updateTodoDecision } from '@/api/todo-definition'
import { validateDecision } from '../resource-contract'
export default { props: { rows: Array, onRefresh: Function }, data() { return { open: false, saving: false, form: {} } }, methods: { show(row) { this.form = { decisionId: row.decisionId, version: row.version || 0, code: row.code || '', title: row.title || '', description: row.description || '', blocking: !!row.blocking, status: row.status || 'OPEN', conclusion: row.conclusion || '', resolution: row.resolution || '' }; this.open = true }, reopen(row) { this.show({ ...row, status: 'OPEN', conclusion: '', resolution: '' }) }, async save() { try { const form = validateDecision(this.form); this.saving = true; const data = { ...form, actionId: `decision-${form.decisionId || 'create'}-${Date.now()}` }; if (form.decisionId) await updateTodoDecision(form.decisionId, data); else await createTodoDecision(data); await this.onRefresh(); this.open = false } catch (error) { this.$modal.msgError(error.message || '保存失败') } finally { this.saving = false } } } }
</script>
